const rid=JSON.parse(await readFile(root+'/latest.json')).release_id;
const manifest=JSON.parse(await readFile(root+'/releases/'+rid+'/manifest.json'));
const doc=manifest.instruments.find(d=>d.slug==='lic');
const list=JSON.parse(await readFile(root+'/releases/'+rid+'/'+doc.document_path)).provisions;
const target=list.find(p=>p.label==='Artículo 193');const index=list.indexOf(target);
const server=createReaderServer(root);await new Promise(r=>server.listen(0,'127.0.0.1',r));
const b=await launch(undefined,{fonts:'blocked'});const p=b.page;
