 await p.viewport(390,844);await p.send('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/lex-mex/?release=${rid}&instrument=lic&provision=${encodeURIComponent(target.id)}`});
 await p.until("performance.getEntriesByName('reader:target-settled').length>0",15000);
 const initial=await p.eval('__probe.ui()');
 await p.send('Debugger.enable');
 const bp=await p.send('Debugger.setBreakpointByUrl',{urlRegex:'/reader.js$',lineNumber:174});
 let forced=false,observedState;
 const paused=new Promise((resolve,reject)=>{
  p.ws.addEventListener('message',async e=>{const m=JSON.parse(e.data);if(m.method!=='Debugger.paused')return;
   try{const cf=m.params.callFrames[0].callFrameId;
    const x=await p.send('Debugger.evaluateOnCallFrame',{callFrameId:cf,expression:'realigns=41; nudges=401; recoveries=30; settleTarget=null; ({held,realigns,nudges,recoveries,userScrolled,off:drift(held)})',returnByValue:true});observedState=x.result.value;forced=true;
    await p.send('Debugger.removeBreakpoint',{breakpointId:bp.breakpointId});await p.send('Debugger.resume');resolve();
   }catch(e){reject(e);}
  });
 });
 await p.send('Runtime.evaluate',{expression:"document.querySelector('#flow article').style.paddingBottom='1400px';"});
 await Promise.race([paused,new Promise((_,rej)=>setTimeout(()=>rej(Error('no pause')),10000))]);
 await new Promise(r=>setTimeout(r,1800));
 const after=await p.eval(`({ui:__probe.ui(),truth:__probe.truth(),offset:__probe.top(${index})-document.getElementById('active-bar').offsetHeight,exhausted:performance.getEntriesByName('reader:hold-recovery-exhausted').length,scrolls:window.__scrolls})`);
 const copy=await p.eval("__probe.copy('copy-text')");
 await p.eval('__probe.scrollBy(100)');await new Promise(r=>setTimeout(r,700));const afterIntent=await p.eval('({ui:__probe.ui(),truth:__probe.truth(),intent:performance.getEntriesByName("reader:intent").length})');
 const out={method:'Fault-injected counters via CDP on unmodified shipped JS, synthetic padding change; branch reachability test, not evidence of 30 natural storms',initial,forced,observedState,after:{...after,truthLabel:list[after.truth].label,copyEqualsRequested:copy===target.text},afterIntent:{...afterIntent,truthLabel:list[afterIntent.truth].label}};
 await writeFile('/tmp/lex-r5-codex-cap-probe.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));
}finally{await b.close();await new Promise(r=>server.close(r));}

