import {launch} from '/Users/jr/Dev/lex-mex-reader-four/reader/browser-check.mjs';import {createReaderServer} from '/Users/jr/Dev/lex-mex-reader-four/reader/serve.mjs';import {readFile,writeFile} from 'node:fs/promises';
const root='/Users/jr/Dev/lex-mex-reader-four/.work/r10-preferred-a';const rid=JSON.parse(await readFile(root+'/latest.json')).release_id;const manifest=JSON.parse(await readFile(root+'/releases/'+rid+'/manifest.json'));const d=manifest.instruments.find(d=>d.slug==='lic');const list=JSON.parse(await readFile(root+'/releases/'+rid+'/'+d.document_path)).provisions;const t=list.find(p=>p.label==='Artículo 193');const server=createReaderServer(root);await new Promise(r=>server.listen(0,'127.0.0.1',r));const b=await launch(undefined,{fonts:1500});const p=b.page;const steps=[];let result;
async function step(name,fn){const t=Date.now();console.log('START',name);const value=await Promise.race([fn(),new Promise((_,rej)=>{const timer=setTimeout(()=>rej(Error('Timeout '+name)),20000);timer.unref();})]);steps.push({name,ms:Date.now()-t});console.log('DONE',name);return value;}
try{await p.viewport(1440,900);await p.send('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/lex-mex/?release=${rid}&instrument=lic&provision=${encodeURIComponent(t.id)}`});await p.until('window.__probe&&__probe.ready()',20000);const fontsAtAction=await p.eval('document.fonts.status');await step('emulate',()=>p.send('Emulation.setTouchEmulationEnabled',{enabled:true}));const c=await p.eval("(()=>{const r=document.getElementById('article').getBoundingClientRect();return{x:Math.round(r.left+r.width/2),y:Math.round(r.top+r.height*0.6)};})()");await step('touchStart',()=>p.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[c]}));await step('touchMove',()=>p.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:c.x,y:c.y+2}]}));await step('touchEnd',()=>p.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]}));await p.until("document.fonts.status==='loaded'",16000);await new Promise(r=>setTimeout(r,1500));const ui=await p.eval('__probe.ui()'),truth=list[await p.eval('__probe.truth()')];const copy=await p.eval("__probe.copy('copy-text')");result={fontsAtAction,steps,ui,truth:truth.label,copyExact:copy===t.text,intents:await p.eval("performance.getEntriesByName('reader:intent').length")};}catch(e){result={steps,error:String(e)};}finally{await b.close();await new Promise(r=>server.close(r));}await writeFile('/tmp/lex-r5-codex-touch-probe.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));
